###############################################################################
## Adaptive Rejection Sampling (Gilks & Wild, 1992)
##
## Main entry point:  ars(density_function, domain, n = sample_count)
## Formal test suite:  test()
##
## Style / design notes
## --------------------
## * Purely functional (no S4/R5 classes); every discrete task lives in its own
##   auxiliary function whose name is snake_case and starts with a verb
##   (make_*, build_*, sample_*, eval_*, check_*, validate_*).
## * The "hull" object is a plain list passed between the auxiliary functions;
##   it fully describes the current piecewise-exponential envelope.
## * All numerics are done on the log scale with log-sum-exp style guards so
##   that densities with tiny/huge normalising constants are handled safely.
###############################################################################


## ---------------------------------------------------------------------------
## 1. Input validation
## ---------------------------------------------------------------------------

#' Coerce the user supplied density into a vectorized R function.
#'
#' Accepts a function, the name of a function (character), or an unevaluated
#' expression / formula in the variable `x` (e.g. quote(exp(-x^2/2))).
make_density_function <- function(density_function) {
  if (is.function(density_function)) {
    return(density_function)
  }
  if (is.character(density_function) && length(density_function) == 1L) {
    fun <- try(match.fun(density_function), silent = TRUE)
    if (inherits(fun, "try-error")) {
      stop("ars: 'density_function' is a character string that does not name a function")
    }
    return(fun)
  }
  if (inherits(density_function, "formula")) {
    rhs <- density_function[[length(density_function)]]
    return(function(x) eval(rhs, list(x = x), environment(density_function)))
  }
  if (is.call(density_function) || is.name(density_function) ||
      is.expression(density_function)) {
    expr <- if (is.expression(density_function)) density_function[[1L]] else density_function
    return(function(x) eval(expr, list(x = x), parent.frame()))
  }
  stop("ars: 'density_function' must be a function, a function name, or an expression in 'x'")
}


#' Validate every user supplied argument; stops with an informative message.
#'
#' @return a list with the cleaned up components (fun, lower, upper, n).
validate_ars_inputs <- function(density_function, domain, n) {

  ## --- number of samples ---------------------------------------------------
  if (missing(n) || is.null(n)) {
    stop("ars: 'n' (number of samples) must be supplied")
  }
  if (!is.numeric(n) || length(n) != 1L) {
    stop("ars: 'n' must be a single number")
  }
  if (!is.finite(n)) {
    stop("ars: 'n' must be a finite number")
  }
  if (n <= 0) {
    stop("ars: 'n' must be a positive integer (got ", n, ")")
  }
  if (abs(n - round(n)) > 1e-8) {
    stop("ars: 'n' must be an integer (got ", n, ")")
  }
  n <- as.integer(round(n))

  ## --- domain --------------------------------------------------------------
  if (is.null(domain)) domain <- c(-Inf, Inf)
  if (!is.numeric(domain) || length(domain) != 2L) {
    stop("ars: 'domain' must be a numeric vector of length 2, e.g. c(-Inf, Inf)")
  }
  if (any(is.na(domain))) {
    stop("ars: 'domain' must not contain NA/NaN")
  }
  lower <- domain[1L]
  upper <- domain[2L]
  if (!(lower < upper)) {
    stop("ars: invalid domain - lower bound must be strictly less than upper bound")
  }

  ## --- density -------------------------------------------------------------
  fun <- make_density_function(density_function)

  probe <- if (is.finite(lower) && is.finite(upper)) {
    lower + (upper - lower) * c(0.25, 0.5, 0.75)
  } else if (is.finite(lower)) {
    lower + c(0.5, 1, 2)
  } else if (is.finite(upper)) {
    upper - c(2, 1, 0.5)
  } else {
    c(-1, 0, 1)
  }
  value <- try(fun(probe), silent = TRUE)
  if (inherits(value, "try-error")) {
    stop("ars: 'density_function' could not be evaluated on the domain: ",
         attr(value, "condition")$message)
  }
  if (!is.numeric(value)) {
    stop("ars: 'density_function' must return numeric values")
  }
  if (length(value) != length(probe)) {
    stop("ars: 'density_function' must be vectorized (return one value per input)")
  }
  if (any(is.na(value))) {
    stop("ars: 'density_function' returned NA/NaN inside the domain")
  }
  if (any(value < 0)) {
    stop("ars: 'density_function' returned negative values - not a density")
  }

  list(fun = fun, lower = lower, upper = upper, n = n)
}


## ---------------------------------------------------------------------------
## 2. Log density and its derivative
## ---------------------------------------------------------------------------

#' Build h(x) = log f(x), vectorized, guarding against f(x) <= 0.
make_log_density <- function(fun, ..., log_input = FALSE) {
  function(x) {
    value <- fun(x, ...)
    if (length(value) != length(x)) {
      value <- rep_len(value, length(x))
    }
    value <- as.numeric(value)
    if (log_input) {
      value[is.na(value)] <- -Inf
      return(value)
    }
    out <- rep(-Inf, length(x))
    ok <- !is.na(value) & value > 0
    out[ok] <- log(value[ok])
    out
  }
}


#' Numerical derivative h'(x) by (clamped) central differences.
make_log_density_derivative <- function(h, lower, upper) {
  function(x) {
    delta <- pmax(1e-7, 1e-6 * pmax(1, abs(x)))
    left  <- pmax(x - delta, lower + 1e-12 * pmax(1, abs(lower)))
    right <- pmin(x + delta, upper - 1e-12 * pmax(1, abs(upper)))
    left  <- ifelse(is.finite(left),  left,  x - delta)
    right <- ifelse(is.finite(right), right, x + delta)
    bad <- right <= left
    if (any(bad)) {
      left[bad]  <- x[bad] - delta[bad]
      right[bad] <- x[bad] + delta[bad]
    }
    (h(right) - h(left)) / (right - left)
  }
}


## ---------------------------------------------------------------------------
## 3. Initialisation of the starting abscissae
## ---------------------------------------------------------------------------

#' Find starting points x_1 < ... < x_k with finite h and, for unbounded
#' domains, h'(x_1) > 0 and h'(x_k) < 0 (condition of Gilks & Wild 1992).
initialize_abscissae <- function(h, hprime, lower, upper, max_step = 60L) {

  finite_h <- function(x) is.finite(h(x))

  ## a point strictly inside the domain where the density is positive
  find_interior <- function() {
    candidates <- if (is.finite(lower) && is.finite(upper)) {
      lower + (upper - lower) * c(0.5, 0.25, 0.75, 0.1, 0.9, 0.01, 0.99)
    } else if (is.finite(lower)) {
      lower + c(1, 0.5, 0.1, 2, 5, 10, 50, 1e-3)
    } else if (is.finite(upper)) {
      upper - c(1, 0.5, 0.1, 2, 5, 10, 50, 1e-3)
    } else {
      c(0, 1, -1, 5, -5, 20, -20, 100, -100)
    }
    for (x in candidates) if (finite_h(x)) return(x)
    stop("ars: could not find a point in the domain where the density is positive")
  }

  x0 <- find_interior()

  ## search leftwards for positive slope (needed when lower == -Inf)
  search_left <- function(x) {
    step <- max(1, abs(x) * 0.5)
    xs <- x
    for (i in seq_len(max_step)) {
      if (is.finite(h(xs)) && hprime(xs) > 0) return(xs)
      xs <- xs - step
      step <- step * 2
    }
    stop("ars: cannot initialise - no point with positive log-density slope found; ",
         "the density may not be log-concave or not integrable on this domain")
  }

  ## search rightwards for negative slope (needed when upper == Inf)
  search_right <- function(x) {
    step <- max(1, abs(x) * 0.5)
    xs <- x
    for (i in seq_len(max_step)) {
      if (is.finite(h(xs)) && hprime(xs) < 0) return(xs)
      xs <- xs + step
      step <- step * 2
    }
    stop("ars: cannot initialise - no point with negative log-density slope found; ",
         "the density may not be log-concave or not integrable on this domain")
  }

  ## bracket the interior point on both sides with points of finite h
  shrink_towards <- function(bound, from) {
    x <- (bound + from) / 2
    for (i in seq_len(max_step)) {
      if (finite_h(x)) return(x)
      x <- (x + from) / 2
    }
    stop("ars: could not find a valid starting point next to the domain boundary")
  }

  x_left  <- if (is.finite(lower)) shrink_towards(lower, x0) else search_left(x0)
  x_right <- if (is.finite(upper)) shrink_towards(upper, x0) else search_right(x0)

  points <- sort(unique(c(x_left, x0, x_right)))
  points <- points[is.finite(h(points))]
  if (length(points) < 2L) {
    stop("ars: could not initialise the sampler with at least two starting points")
  }
  points
}


## ---------------------------------------------------------------------------
## 4. The upper / lower hulls
## ---------------------------------------------------------------------------

#' Build the hull object: tangent intersection points z, per-piece log masses.
build_hull <- function(x, hx, hpx, lower, upper, tol = 1e-8) {

  k <- length(x)
  check_log_concavity(x, hx, hpx, tol = tol)

  ## intersection abscissae z_j of tangents at x_j and x_{j+1}
  z <- numeric(0)
  if (k > 1L) {
    num <- hx[-1L] - hx[-k] - x[-1L] * hpx[-1L] + x[-k] * hpx[-k]
    den <- hpx[-k] - hpx[-1L]
    z <- ifelse(abs(den) < 1e-12, (x[-k] + x[-1L]) / 2, num / den)
    z <- pmin(pmax(z, x[-k]), x[-1L])   ## numerical safety: z_j in [x_j, x_{j+1}]
  }
  zfull <- c(lower, z, upper)

  ## log of the integral of exp(u) over each piece  [z_{j-1}, z_j]
  log_mass <- vapply(seq_len(k), function(j) {
    zl <- zfull[j]; zr <- zfull[j + 1L]
    m <- hpx[j]
    if (zr <= zl) return(-Inf)
    if (abs(m) < 1e-10) {
      if (!is.finite(zr - zl)) {
        stop("ars: the upper envelope has infinite mass - the density does not ",
             "appear to be log-concave / integrable on this domain")
      }
      return(hx[j] + log(zr - zl))
    }
    a <- m * (zl - x[j])
    b <- m * (zr - x[j])
    if (!is.finite(max(a, b))) {
      stop("ars: the upper envelope has infinite mass - the density does not ",
           "appear to be log-concave / integrable on this domain")
    }
    width <- abs(b - a)
    hx[j] + max(a, b) + log(-expm1(-width)) - log(abs(m))
  }, numeric(1))

  if (all(!is.finite(log_mass)) || all(log_mass == -Inf)) {
    stop("ars: degenerate upper envelope (zero mass)")
  }
  log_mass[is.na(log_mass)] <- -Inf

  offset <- max(log_mass[is.finite(log_mass)])
  weights <- exp(log_mass - offset)
  weights[!is.finite(weights)] <- 0
  weights <- weights / sum(weights)

  list(x = x, hx = hx, hpx = hpx, z = zfull,
       log_mass = log_mass, weights = weights,
       lower = lower, upper = upper)
}


#' Evaluate the piecewise-linear upper hull u(x) (in log scale).
eval_upper_hull <- function(hull, xs) {
  j <- findInterval(xs, hull$z, rightmost.closed = TRUE, all.inside = TRUE)
  hull$hx[j] + (xs - hull$x[j]) * hull$hpx[j]
}


#' Evaluate the piecewise-linear lower hull (squeezing function) l(x).
#' Returns -Inf outside [x_1, x_k], as in Gilks & Wild (1992).
eval_lower_hull <- function(hull, xs) {
  x <- hull$x; hx <- hull$hx; k <- length(x)
  out <- rep(-Inf, length(xs))
  inside <- xs >= x[1L] & xs <= x[k]
  if (any(inside) && k > 1L) {
    xi <- xs[inside]
    j <- pmin(pmax(findInterval(xi, x, rightmost.closed = TRUE), 1L), k - 1L)
    out[inside] <- ((x[j + 1L] - xi) * hx[j] + (xi - x[j]) * hx[j + 1L]) /
                   (x[j + 1L] - x[j])
  }
  out
}


## ---------------------------------------------------------------------------
## 5. Log-concavity diagnostics
## ---------------------------------------------------------------------------

#' A log-concave density has a non-increasing derivative of its log.
#' Stops with an informative error as soon as this is violated.
check_log_concavity <- function(x, hx, hpx, tol = 1e-8) {
  if (any(!is.finite(hx))) {
    stop("ars: log-density is not finite at an interior abscissa - the support ",
         "of the density must be a single interval (log-concavity violated)")
  }
  if (any(!is.finite(hpx))) {
    stop("ars: the derivative of the log-density is not finite - cannot proceed")
  }
  if (length(x) > 1L) {
    d <- diff(hpx)
    scale <- max(1, max(abs(hpx)))
    if (any(d > tol * scale * 100)) {
      bad <- which(d > tol * scale * 100)[1L]
      stop(sprintf(paste0("ars: density is not log-concave - the derivative of ",
                          "log f increases between x = %g (h' = %g) and x = %g (h' = %g)"),
                   x[bad], hpx[bad], x[bad + 1L], hpx[bad + 1L]))
    }
  }
  invisible(TRUE)
}


#' Check that the envelope really dominates the log density at a sampled point.
check_envelope <- function(x_star, h_star, u_star, tol = 1e-6) {
  if (is.finite(h_star) && h_star > u_star + tol * max(1, abs(u_star))) {
    stop(sprintf(paste0("ars: density is not log-concave - log f(%g) = %g exceeds ",
                        "the upper envelope value %g"), x_star, h_star, u_star))
  }
  invisible(TRUE)
}


## ---------------------------------------------------------------------------
## 6. Sampling from the upper hull
## ---------------------------------------------------------------------------

#' Draw `m` points from the normalised piecewise-exponential envelope.
sample_upper_hull <- function(hull, m = 1L) {
  j <- sample.int(length(hull$weights), size = m, replace = TRUE,
                  prob = hull$weights)
  w <- runif(m)
  zl <- hull$z[j]; zr <- hull$z[j + 1L]
  slope <- hull$hpx[j]; xj <- hull$x[j]

  out <- numeric(m)
  flat <- abs(slope) < 1e-10
  if (any(flat)) out[flat] <- zl[flat] + w[flat] * (zr[flat] - zl[flat])
  if (any(!flat)) {
    i <- which(!flat)
    a <- slope[i] * (zl[i] - xj[i])
    b <- slope[i] * (zr[i] - xj[i])
    ## inverse cdf on the log scale, stable for either sign of the slope
    val <- ifelse(b >= a,
                  b + log(exp(a - b) + w[i] * (1 - exp(a - b))),
                  a + log1p(w[i] * expm1(b - a)))
    out[i] <- xj[i] + val / slope[i]
  }
  ## numerical safety: keep the draws inside their own piece
  out <- pmin(pmax(out, zl), zr)
  out[!is.finite(out)] <- (zl[!is.finite(out)] + zr[!is.finite(out)]) / 2
  out
}


#' Insert new abscissae into the (sorted) hull support and rebuild the hull.
update_hull <- function(hull, new_x, new_h, new_hp, tol = 1e-8) {
  keep <- !duplicated(c(hull$x, new_x))
  x   <- c(hull$x, new_x)[keep]
  hx  <- c(hull$hx, new_h)[keep]
  hpx <- c(hull$hpx, new_hp)[keep]
  ord <- order(x)
  build_hull(x[ord], hx[ord], hpx[ord], hull$lower, hull$upper, tol = tol)
}


## ---------------------------------------------------------------------------
## 7. Main function
## ---------------------------------------------------------------------------

#' Adaptive rejection sampling (Gilks & Wild, 1992)
#'
#' @param density_function function / function name / expression in x giving the
#'        (possibly unnormalised) density, vectorized.
#' @param domain numeric vector of length 2 giving the support, may be infinite.
#' @param n number of samples to draw.
#' @param log_density set TRUE if `density_function` already returns log f.
#' @param max_points maximum number of abscissae kept in the hull.
#' @param ... further arguments passed on to `density_function`.
#' @return numeric vector of length n containing i.i.d. draws from the density.
ars <- function(density_function, domain = c(-Inf, Inf), n = 100,
                log_density = FALSE, max_points = 500L, ...) {

  checked <- validate_ars_inputs(density_function, domain, n)
  fun <- checked$fun; lower <- checked$lower; upper <- checked$upper
  n <- checked$n

  h      <- make_log_density(fun, ..., log_input = log_density)
  hprime <- make_log_density_derivative(h, lower, upper)

  x   <- initialize_abscissae(h, hprime, lower, upper)
  hx  <- h(x)
  hpx <- hprime(x)
  hull <- build_hull(x, hx, hpx, lower, upper)

  samples <- numeric(n)
  filled <- 0L
  iteration <- 0L
  max_iterations <- 1000L * n + 10000L

  while (filled < n) {
    iteration <- iteration + 1L
    if (iteration > max_iterations) {
      stop("ars: exceeded the maximum number of iterations without collecting ",
           n, " samples; the density may be badly behaved")
    }

    ## batch size grows with what is left to do (efficiency, same algorithm)
    batch <- max(1L, min(n - filled, 100L))
    x_star <- sample_upper_hull(hull, batch)
    w <- runif(batch)

    u_star <- eval_upper_hull(hull, x_star)
    l_star <- eval_lower_hull(hull, x_star)

    ## --- squeezing test ----------------------------------------------------
    squeezed <- log(w) <= (l_star - u_star)
    accepted <- squeezed

    ## --- rejection test (only where the squeeze failed) --------------------
    need <- which(!squeezed)
    new_x <- numeric(0); new_h <- numeric(0); new_hp <- numeric(0)
    if (length(need) > 0L) {
      h_star <- h(x_star[need])
      for (i in seq_along(need)) {
        check_envelope(x_star[need[i]], h_star[i], u_star[need[i]])
      }
      accepted[need] <- log(w[need]) <= (h_star - u_star[need])
      ## adapt: add the evaluated points to the hull
      ok <- is.finite(h_star)
      if (any(ok) && length(hull$x) < max_points) {
        cand <- x_star[need][ok]
        new_x  <- cand
        new_h  <- h_star[ok]
        new_hp <- hprime(cand)
      }
    }

    n_acc <- sum(accepted)
    if (n_acc > 0L) {
      take <- min(n_acc, n - filled)
      samples[(filled + 1L):(filled + take)] <- x_star[accepted][seq_len(take)]
      filled <- filled + take
    }

    if (length(new_x) > 0L) {
      hull <- update_hull(hull, new_x, new_h, new_hp)
    }
  }

  samples
}


###############################################################################
## 8. Formal test suite
###############################################################################

#' Pretty printer for a single test outcome.
report_test <- function(name, passed, mean_value = NA_real_, sd_value = NA_real_,
                        detail = "") {
  status <- if (isTRUE(passed)) "PASS" else "FAIL"
  msg <- sprintf("%s: %s", name, status)
  if (is.finite(mean_value) || is.finite(sd_value)) {
    msg <- sprintf("%s  (mean = %.4f, sd = %.4f)", msg, mean_value, sd_value)
  }
  if (nzchar(detail)) msg <- sprintf("%s  [%s]", msg, detail)
  cat(msg, "\n", sep = "")
  isTRUE(passed)
}


#' Compare a sample against a known cdf with a Kolmogorov-Smirnov test plus
#' checks on the first two moments.
check_distribution <- function(name, samples, cdf, true_mean, true_sd,
                               alpha = 1e-4, tol_mean = 0.15, tol_sd = 0.15,
                               verbose = TRUE) {
  m <- mean(samples); s <- sd(samples)
  ks <- suppressWarnings(stats::ks.test(samples, cdf))
  ok_ks   <- ks$p.value > alpha
  ok_mean <- abs(m - true_mean) < tol_mean * max(1, abs(true_sd))
  ok_sd   <- abs(s - true_sd) < tol_sd * max(1, abs(true_sd))
  passed  <- ok_ks && ok_mean && ok_sd
  if (verbose) {
    report_test(name, passed, m, s,
                sprintf("n = %d, KS p = %.3g, truth: mean = %.4f, sd = %.4f",
                        length(samples), ks$p.value, true_mean, true_sd))
  }
  passed
}


#' Check that an expression fails (used for the input-validation tests).
check_error <- function(name, expr, verbose = TRUE) {
  res <- try(force(expr), silent = TRUE)
  passed <- inherits(res, "try-error")
  detail <- if (passed) {
    msg <- conditionMessage(attr(res, "condition"))
    paste0("error: ", substr(gsub("\n", " ", msg), 1, 90))
  } else {
    "no error was raised"
  }
  if (verbose) report_test(name, passed, detail = detail)
  passed
}


#' Unit tests of the auxiliary modules (hull construction, envelope sampling).
test_modules <- function(verbose = TRUE) {
  results <- logical(0)

  ## ---- upper hull dominates and lower hull is dominated by h -------------
  cat("-- Module tests -------------------------------------------------\n")
  h      <- make_log_density(dnorm)
  hprime <- make_log_density_derivative(h, -Inf, Inf)

  cat("Checking numerical derivative of the log density against d/dx(-x^2/2) = -x\n")
  grid <- c(-3, -1, -0.2, 0, 0.5, 2, 4)
  results <- c(results, report_test("derivative_accuracy",
              max(abs(hprime(grid) - (-grid))) < 1e-4))

  cat("Checking that the upper hull majorises and the lower hull minorises log f\n")
  x   <- c(-2, 0, 1.5)
  hull <- build_hull(x, h(x), hprime(x), -Inf, Inf)
  grid <- seq(-4, 4, length.out = 401)
  u <- eval_upper_hull(hull, grid)
  l <- eval_lower_hull(hull, grid)
  hv <- h(grid)
  results <- c(results, report_test("upper_hull_majorises", all(u >= hv - 1e-8)))
  results <- c(results, report_test("lower_hull_minorises", all(l <= hv + 1e-8)))
  results <- c(results, report_test("hull_ordering",
              all(diff(hull$z) >= -1e-8) && all(l <= u + 1e-8)))

  cat("Checking that draws from the envelope match the envelope's own cdf\n")
  set.seed(11)
  env <- sample_upper_hull(hull, 20000)
  ## numerical cdf of exp(u) on a fine grid
  gg <- seq(-12, 12, length.out = 20001)
  dens <- exp(eval_upper_hull(hull, gg))
  cdf_vals <- cumsum((dens[-1] + dens[-length(dens)]) / 2 * diff(gg))
  cdf_vals <- c(0, cdf_vals) / cdf_vals[length(cdf_vals)]
  env_cdf <- function(q) approx(gg, cdf_vals, xout = q, rule = 2)$y
  ks <- suppressWarnings(stats::ks.test(env, env_cdf))
  results <- c(results, report_test("envelope_sampler_matches_envelope",
              ks$p.value > 1e-4, mean(env), sd(env),
              sprintf("KS p = %.3g", ks$p.value)))

  cat("Checking that the hull update keeps the abscissae sorted and valid\n")
  hull2 <- update_hull(hull, c(0.7, -3), h(c(0.7, -3)), hprime(c(0.7, -3)))
  results <- c(results, report_test("hull_update_sorted",
              !is.unsorted(hull2$x) && length(hull2$x) == 5L &&
              all(eval_upper_hull(hull2, grid) >= hv - 1e-8)))

  cat("Checking that the log-concavity module rejects an increasing h'\n")
  results <- c(results, check_error("log_concavity_module_detects_violation",
              check_log_concavity(c(0, 1, 2), c(0, 0, 0), c(-1, 0.5, 1))))

  invisible(results)
}


#' Full formal test suite.  Prints an informative log and a final summary.
#' @param n number of samples used in the distributional tests.
#' @return (invisibly) TRUE if every test passed.
test <- function(n = 5000, seed = 20260729, write_files = TRUE) {

  set.seed(seed)
  cat("=================================================================\n")
  cat(" Adaptive Rejection Sampling (Gilks & Wild 1992) - test suite\n")
  cat(sprintf(" sample size per distributional test: %d, seed: %d\n", n, seed))
  cat("=================================================================\n")

  results <- logical(0)
  results <- c(results, test_modules())

  cat("\n-- Distributional tests (samples vs. known truth) ----------------\n")

  cat("Sampling from N(0, 1) on (-Inf, Inf)\n")
  normal_samples <- ars(dnorm, c(-Inf, Inf), n = n)
  results <- c(results, check_distribution("NORMAL_STANDARD", normal_samples,
                                           pnorm, 0, 1))

  cat("Sampling from N(4, 2^2) on (-Inf, Inf)\n")
  s <- ars(function(x) dnorm(x, mean = 4, sd = 2), c(-Inf, Inf), n = n)
  results <- c(results, check_distribution("NORMAL_SHIFTED", s,
                                           function(q) pnorm(q, 4, 2), 4, 2,
                                           tol_mean = 0.15, tol_sd = 0.15))

  cat("Sampling from an unnormalised normal kernel exp(-x^2/2) given as an expression\n")
  s <- ars(quote(exp(-x^2 / 2)), c(-Inf, Inf), n = n)
  results <- c(results, check_distribution("NORMAL_UNNORMALISED", s, pnorm, 0, 1))

  cat("Sampling from Exponential(rate = 1) on (0, Inf)\n")
  exponential_samples <- ars(dexp, c(0, Inf), n = n)
  results <- c(results, check_distribution("EXPONENTIAL", exponential_samples,
                                           pexp, 1, 1))

  cat("Sampling from Gamma(shape = 3, rate = 2) on (0, Inf)\n")
  s <- ars(function(x) dgamma(x, shape = 3, rate = 2), c(0, Inf), n = n)
  results <- c(results, check_distribution("GAMMA_3_2", s,
                                           function(q) pgamma(q, 3, 2),
                                           3 / 2, sqrt(3) / 2))

  cat("Sampling from Beta(2, 3) on the bounded domain (0, 1)\n")
  s <- ars(function(x) dbeta(x, 2, 3), c(0, 1), n = n)
  results <- c(results, check_distribution("BETA_2_3", s,
                                           function(q) pbeta(q, 2, 3),
                                           0.4, sqrt(2 * 3 / (25 * 6))))

  cat("Sampling from Uniform(0, 1) - the flat (zero curvature) edge case\n")
  s <- ars(dunif, c(0, 1), n = n)
  results <- c(results, check_distribution("UNIFORM_0_1", s, punif,
                                           0.5, 1 / sqrt(12)))

  cat("Sampling from a truncated normal on the bounded domain (-1, 2)\n")
  s <- ars(dnorm, c(-1, 2), n = n)
  const <- pnorm(2) - pnorm(-1)
  tn_cdf <- function(q) (pnorm(q) - pnorm(-1)) / const
  tn_mean <- (dnorm(-1) - dnorm(2)) / const
  tn_var <- 1 + ((-1) * dnorm(-1) - 2 * dnorm(2)) / const - tn_mean^2
  results <- c(results, check_distribution("TRUNCATED_NORMAL", s, tn_cdf,
                                           tn_mean, sqrt(tn_var)))

  cat("Sampling from a Logistic(0, 1) density (log-concave, heavier tails)\n")
  s <- ars(dlogis, c(-Inf, Inf), n = n)
  results <- c(results, check_distribution("LOGISTIC", s, plogis, 0,
                                           pi / sqrt(3), tol_mean = 0.2,
                                           tol_sd = 0.2))

  cat("\n-- Sanity check: output must not be uniform noise ----------------\n")
  ks_unif <- suppressWarnings(stats::ks.test(
    (normal_samples - min(normal_samples)) /
      diff(range(normal_samples)), punif))
  results <- c(results, report_test("NORMAL_IS_NOT_UNIFORM",
              ks_unif$p.value < 1e-3, mean(normal_samples), sd(normal_samples),
              sprintf("KS p vs uniform = %.3g (small is good)", ks_unif$p.value)))

  cat("\n-- Input validation tests ----------------------------------------\n")
  results <- c(results, check_error("INVALID_N_NEGATIVE", ars(dnorm, c(-Inf, Inf), n = -10)))
  results <- c(results, check_error("INVALID_N_ZERO", ars(dnorm, c(-Inf, Inf), n = 0)))
  results <- c(results, check_error("INVALID_N_NON_INTEGER", ars(dnorm, c(-Inf, Inf), n = 2.5)))
  results <- c(results, check_error("INVALID_N_NOT_NUMERIC", ars(dnorm, c(-Inf, Inf), n = "ten")))
  results <- c(results, check_error("INVALID_DOMAIN_ORDER", ars(dnorm, c(5, -5), n = 10)))
  results <- c(results, check_error("INVALID_DOMAIN_LENGTH", ars(dnorm, c(0), n = 10)))
  results <- c(results, check_error("INVALID_DOMAIN_NA", ars(dnorm, c(NA, 1), n = 10)))
  results <- c(results, check_error("INVALID_DENSITY_TYPE", ars(42, c(-Inf, Inf), n = 10)))
  results <- c(results, check_error("INVALID_DENSITY_NEGATIVE",
                                    ars(function(x) -abs(x), c(-1, 1), n = 10)))

  cat("\n-- Log-concavity detection tests ---------------------------------\n")
  results <- c(results, check_error("NON_LOG_CONCAVE_CAUCHY",
                                    ars(dcauchy, c(-Inf, Inf), n = 200)))
  results <- c(results, check_error("NON_LOG_CONCAVE_T_DF2",
                                    ars(function(x) dt(x, df = 2), c(-Inf, Inf), n = 200)))
  results <- c(results, check_error("NON_LOG_CONCAVE_MIXTURE",
                                    ars(function(x) 0.5 * dnorm(x, -4) + 0.5 * dnorm(x, 4),
                                        c(-Inf, Inf), n = 200)))
  results <- c(results, check_error("NON_LOG_CONCAVE_PARETO",
                                    ars(function(x) 1 / x^2, c(1, Inf), n = 200)))

  if (isTRUE(write_files)) {
    cat("\n-- Writing sample files ------------------------------------------\n")
    write.table(normal_samples, file = "/app/normal_samples.txt",
                row.names = FALSE, col.names = FALSE)
    write.table(exponential_samples, file = "/app/exponential_samples.txt",
                row.names = FALSE, col.names = FALSE)
    cat(sprintf("wrote /app/normal_samples.txt (%d values, mean = %.4f, sd = %.4f)\n",
                length(normal_samples), mean(normal_samples), sd(normal_samples)))
    cat(sprintf("wrote /app/exponential_samples.txt (%d values, mean = %.4f, sd = %.4f)\n",
                length(exponential_samples), mean(exponential_samples),
                sd(exponential_samples)))
  }

  cat("\n=================================================================\n")
  cat(sprintf(" SUMMARY: %d of %d tests passed\n", sum(results), length(results)))
  cat(sprintf(" OVERALL: %s\n", if (all(results)) "PASS" else "FAIL"))
  cat("=================================================================\n")

  invisible(all(results))
}


## Allow `Rscript /app/ars.R` to run the test suite directly.
if (!interactive() && identical(environment(), globalenv()) &&
    length(sys.frames()) == 0L) {
  args <- commandArgs(trailingOnly = TRUE)
  if (length(args) > 0L && args[1L] %in% c("test", "--test")) test()
}

###############################################################################
## Adaptive Rejection Sampling (Gilks & Wild, 1992)
##
## Main entry point:  ars(density_function, domain, n = sample_count)
## Formal test suite:  test()
##
## Style / design notes
## --------------------
## * Purely functional (no S4/R5 classes); every discrete task lives in its own
##   auxiliary function whose name is snake_case and starts with a verb
##   (make_*, build_*, sample_*, eval_*, check_*, validate_*).
## * The "hull" object is a plain list passed between the auxiliary functions;
##   it fully describes the current piecewise-exponential envelope.
## * All numerics are done on the log scale with log-sum-exp style guards so
##   that densities with tiny/huge normalising constants are handled safely.
###############################################################################


## ---------------------------------------------------------------------------
## 1. Input validation
## ---------------------------------------------------------------------------

#' Coerce the user supplied density into a vectorized R function.
#'
#' Accepts a function, the name of a function (character), or an unevaluated
#' expression / formula in the variable `x` (e.g. quote(exp(-x^2/2))).
make_density_function <- function(density_function) {
  if (is.function(density_function)) {
    return(density_function)
  }
  if (is.character(density_function) && length(density_function) == 1L) {
    fun <- try(match.fun(density_function), silent = TRUE)
    if (inherits(fun, "try-error")) {
      stop("ars: 'density_function' is a character string that does not name a function")
    }
    return(fun)
  }
  if (inherits(density_function, "formula")) {
    rhs <- density_function[[length(density_function)]]
    return(function(x) eval(rhs, list(x = x), environment(density_function)))
  }
  if (is.call(density_function) || is.name(density_function) ||
      is.expression(density_function)) {
    expr <- if (is.expression(density_function)) density_function[[1L]] else density_function
    return(function(x) eval(expr, list(x = x), parent.frame()))
  }
  stop("ars: 'density_function' must be a function, a function name, or an expression in 'x'")
}


#' Validate every user supplied argument; stops with an informative message.
#'
#' @return a list with the cleaned up components (fun, lower, upper, n).
validate_ars_inputs <- function(density_function, domain, n) {

  ## --- number of samples ---------------------------------------------------
  if (missing(n) || is.null(n)) {
    stop("ars: 'n' (number of samples) must be supplied")
  }
  if (!is.numeric(n) || length(n) != 1L) {
    stop("ars: 'n' must be a single number")
  }
  if (!is.finite(n)) {
    stop("ars: 'n' must be a finite number")
  }
  if (n <= 0) {
    stop("ars: 'n' must be a positive integer (got ", n, ")")
  }
  if (abs(n - round(n)) > 1e-8) {
    stop("ars: 'n' must be an integer (got ", n, ")")
  }
  n <- as.integer(round(n))

  ## --- domain --------------------------------------------------------------
  if (is.null(domain)) domain <- c(-Inf, Inf)
  if (!is.numeric(domain) || length(domain) != 2L) {
    stop("ars: 'domain' must be a numeric vector of length 2, e.g. c(-Inf, Inf)")
  }
  if (any(is.na(domain))) {
    stop("ars: 'domain' must not contain NA/NaN")
  }
  lower <- domain[1L]
  upper <- domain[2L]
  if (!(lower < upper)) {
    stop("ars: invalid domain - lower bound must be strictly less than upper bound")
  }

  ## --- density -------------------------------------------------------------
  fun <- make_density_function(density_function)

  probe <- if (is.finite(lower) && is.finite(upper)) {
    lower + (upper - lower) * c(0.25, 0.5, 0.75)
  } else if (is.finite(lower)) {
    lower + c(0.5, 1, 2)
  } else if (is.finite(upper)) {
    upper - c(2, 1, 0.5)
  } else {
    c(-1, 0, 1)
  }
  value <- try(fun(probe), silent = TRUE)
  if (inherits(value, "try-error")) {
    stop("ars: 'density_function' could not be evaluated on the domain: ",
         attr(value, "condition")$message)
  }
  if (!is.numeric(value)) {
    stop("ars: 'density_function' must return numeric values")
  }
  if (length(value) != length(probe)) {
    stop("ars: 'density_function' must be vectorized (return one value per input)")
  }
  if (any(is.na(value))) {
    stop("ars: 'density_function' returned NA/NaN inside the domain")
  }
  if (any(value < 0)) {
    stop("ars: 'density_function' returned negative values - not a density")
  }

  list(fun = fun, lower = lower, upper = upper, n = n)
}


## ---------------------------------------------------------------------------
## 2. Log density and its derivative
## ---------------------------------------------------------------------------

#' Build h(x) = log f(x), vectorized, guarding against f(x) <= 0.
make_log_density <- function(fun, ..., log_input = FALSE) {
  function(x) {
    value <- fun(x, ...)
    if (length(value) != length(x)) {
      value <- rep_len(value, length(x))
    }
    value <- as.numeric(value)
    if (log_input) {
      value[is.na(value)] <- -Inf
      return(value)
    }
    out <- rep(-Inf, length(x))
    ok <- !is.na(value) & value > 0
    out[ok] <- log(value[ok])
    out
  }
}


#' Numerical derivative h'(x) by (clamped) central differences.
make_log_density_derivative <- function(h, lower, upper) {
  function(x) {
    delta <- pmax(1e-7, 1e-6 * pmax(1, abs(x)))
    left  <- pmax(x - delta, lower + 1e-12 * pmax(1, abs(lower)))
    right <- pmin(x + delta, upper - 1e-12 * pmax(1, abs(upper)))
    left  <- ifelse(is.finite(left),  left,  x - delta)
    right <- ifelse(is.finite(right), right, x + delta)
    bad <- right <= left
    if (any(bad)) {
      left[bad]  <- x[bad] - delta[bad]
      right[bad] <- x[bad] + delta[bad]
    }
    (h(right) - h(left)) / (right - left)
  }
}


## ---------------------------------------------------------------------------
## 3. Initialisation of the starting abscissae
## ---------------------------------------------------------------------------

#' Find starting points x_1 < ... < x_k with finite h and, for unbounded
#' domains, h'(x_1) > 0 and h'(x_k) < 0 (condition of Gilks & Wild 1992).
initialize_abscissae <- function(h, hprime, lower, upper, max_step = 60L) {

  finite_h <- function(x) is.finite(h(x))

  ## a point strictly inside the domain where the density is positive
  find_interior <- function() {
    candidates <- if (is.finite(lower) && is.finite(upper)) {
      lower + (upper - lower) * c(0.5, 0.25, 0.75, 0.1, 0.9, 0.01, 0.99)
    } else if (is.finite(lower)) {
      lower + c(1, 0.5, 0.1, 2, 5, 10, 50, 1e-3)
    } else if (is.finite(upper)) {
      upper - c(1, 0.5, 0.1, 2, 5, 10, 50, 1e-3)
    } else {
      c(0, 1, -1, 5, -5, 20, -20, 100, -100)
    }
    for (x in candidates) if (finite_h(x)) return(x)
    stop("ars: could not find a point in the domain where the density is positive")
  }

  x0 <- find_interior()

  ## search leftwards for positive slope (needed when lower == -Inf)
  search_left <- function(x) {
    step <- max(1, abs(x) * 0.5)
    xs <- x
    for (i in seq_len(max_step)) {
      if (is.finite(h(xs)) && hprime(xs) > 0) return(xs)
      xs <- xs - step
      step <- step * 2
    }
    stop("ars: cannot initialise - no point with positive log-density slope found; ",
         "the density may not be log-concave or not integrable on this domain")
  }

  ## search rightwards for negative slope (needed when upper == Inf)
  search_right <- function(x) {
    step <- max(1, abs(x) * 0.5)
    xs <- x
    for (i in seq_len(max_step)) {
      if (is.finite(h(xs)) && hprime(xs) < 0) return(xs)
      xs <- xs + step
      step <- step * 2
    }
    stop("ars: cannot initialise - no point with negative log-density slope found; ",
         "the density may not be log-concave or not integrable on this domain")
  }

  ## bracket the interior point on both sides with points of finite h
  shrink_towards <- function(bound, from) {
    x <- (bound + from) / 2
    for (i in seq_len(max_step)) {
      if (finite_h(x)) return(x)
      x <- (x + from) / 2
    }
    stop("ars: could not find a valid starting point next to the domain boundary")
  }

  x_left  <- if (is.finite(lower)) shrink_towards(lower, x0) else search_left(x0)
  x_right <- if (is.finite(upper)) shrink_towards(upper, x0) else search_right(x0)

  points <- sort(unique(c(x_left, x0, x_right)))
  points <- points[is.finite(h(points))]
  if (length(points) < 2L) {
    stop("ars: could not initialise the sampler with at least two starting points")
  }
  points
}


## ---------------------------------------------------------------------------
## 4. The upper / lower hulls
## ---------------------------------------------------------------------------

#' Build the hull object: tangent intersection points z, per-piece log masses.
build_hull <- function(x, hx, hpx, lower, upper, tol = 1e-8) {

  k <- length(x)
  check_log_concavity(x, hx, hpx, tol = tol)

  ## intersection abscissae z_j of tangents at x_j and x_{j+1}
  z <- numeric(0)
  if (k > 1L) {
    num <- hx[-1L] - hx[-k] - x[-1L] * hpx[-1L] + x[-k] * hpx[-k]
    den <- hpx[-k] - hpx[-1L]
    z <- ifelse(abs(den) < 1e-12, (x[-k] + x[-1L]) / 2, num / den)
    z <- pmin(pmax(z, x[-k]), x[-1L])   ## numerical safety: z_j in [x_j, x_{j+1}]
  }
  zfull <- c(lower, z, upper)

  ## log of the integral of exp(u) over each piece  [z_{j-1}, z_j]
  log_mass <- vapply(seq_len(k), function(j) {
    zl <- zfull[j]; zr <- zfull[j + 1L]
    m <- hpx[j]
    if (zr <= zl) return(-Inf)
    if (abs(m) < 1e-10) {
      if (!is.finite(zr - zl)) {
        stop("ars: the upper envelope has infinite mass - the density does not ",
             "appear to be log-concave / integrable on this domain")
      }
      return(hx[j] + log(zr - zl))
    }
    a <- m * (zl - x[j])
    b <- m * (zr - x[j])
    if (!is.finite(max(a, b))) {
      stop("ars: the upper envelope has infinite mass - the density does not ",
           "appear to be log-concave / integrable on this domain")
    }
    width <- abs(b - a)
    hx[j] + max(a, b) + log(-expm1(-width)) - log(abs(m))
  }, numeric(1))

  if (all(!is.finite(log_mass)) || all(log_mass == -Inf)) {
    stop("ars: degenerate upper envelope (zero mass)")
  }
  log_mass[is.na(log_mass)] <- -Inf

  offset <- max(log_mass[is.finite(log_mass)])
  weights <- exp(log_mass - offset)
  weights[!is.finite(weights)] <- 0
  weights <- weights / sum(weights)

  list(x = x, hx = hx, hpx = hpx, z = zfull,
       log_mass = log_mass, weights = weights,
       lower = lower, upper = upper)
}


#' Evaluate the piecewise-linear upper hull u(x) (in log scale).
eval_upper_hull <- function(hull, xs) {
  j <- findInterval(xs, hull$z, rightmost.closed = TRUE, all.inside = TRUE)
  hull$hx[j] + (xs - hull$x[j]) * hull$hpx[j]
}


#' Evaluate the piecewise-linear lower hull (squeezing function) l(x).
#' Returns -Inf outside [x_1, x_k], as in Gilks & Wild (1992).
eval_lower_hull <- function(hull, xs) {
  x <- hull$x; hx <- hull$hx; k <- length(x)
  out <- rep(-Inf, length(xs))
  inside <- xs >= x[1L] & xs <= x[k]
  if (any(inside) && k > 1L) {
    xi <- xs[inside]
    j <- pmin(pmax(findInterval(xi, x, rightmost.closed = TRUE), 1L), k - 1L)
    out[inside] <- ((x[j + 1L] - xi) * hx[j] + (xi - x[j]) * hx[j + 1L]) /
                   (x[j + 1L] - x[j])
  }
  out
}


## ---------------------------------------------------------------------------
## 5. Log-concavity diagnostics
## ---------------------------------------------------------------------------

#' A log-concave density has a non-increasing derivative of its log.
#' Stops with an informative error as soon as this is violated.
check_log_concavity <- function(x, hx, hpx, tol = 1e-8) {
  if (any(!is.finite(hx))) {
    stop("ars: log-density is not finite at an interior abscissa - the support ",
         "of the density must be a single interval (log-concavity violated)")
  }
  if (any(!is.finite(hpx))) {
    stop("ars: the derivative of the log-density is not finite - cannot proceed")
  }
  if (length(x) > 1L) {
    d <- diff(hpx)
    scale <- max(1, max(abs(hpx)))
    if (any(d > tol * scale * 100)) {
      bad <- which(d > tol * scale * 100)[1L]
      stop(sprintf(paste0("ars: density is not log-concave - the derivative of ",
                          "log f increases between x = %g (h' = %g) and x = %g (h' = %g)"),
                   x[bad], hpx[bad], x[bad + 1L], hpx[bad + 1L]))
    }
  }
  invisible(TRUE)
}


#' Check that the envelope really dominates the log density at a sampled point.
check_envelope <- function(x_star, h_star, u_star, tol = 1e-6) {
  if (is.finite(h_star) && h_star > u_star + tol * max(1, abs(u_star))) {
    stop(sprintf(paste0("ars: density is not log-concave - log f(%g) = %g exceeds ",
                        "the upper envelope value %g"), x_star, h_star, u_star))
  }
  invisible(TRUE)
}


## ---------------------------------------------------------------------------
## 6. Sampling from the upper hull
## ---------------------------------------------------------------------------

#' Draw `m` points from the normalised piecewise-exponential envelope.
sample_upper_hull <- function(hull, m = 1L) {
  j <- sample.int(length(hull$weights), size = m, replace = TRUE,
                  prob = hull$weights)
  w <- runif(m)
  zl <- hull$z[j]; zr <- hull$z[j + 1L]
  slope <- hull$hpx[j]; xj <- hull$x[j]

  out <- numeric(m)
  flat <- abs(slope) < 1e-10
  if (any(flat)) out[flat] <- zl[flat] + w[flat] * (zr[flat] - zl[flat])
  if (any(!flat)) {
    i <- which(!flat)
    a <- slope[i] * (zl[i] - xj[i])
    b <- slope[i] * (zr[i] - xj[i])
    ## inverse cdf on the log scale, stable for either sign of the slope
    val <- ifelse(b >= a,
                  b + log(exp(a - b) + w[i] * (1 - exp(a - b))),
                  a + log1p(w[i] * expm1(b - a)))
    out[i] <- xj[i] + val / slope[i]
  }
  ## numerical safety: keep the draws inside their own piece
  out <- pmin(pmax(out, zl), zr)
  out[!is.finite(out)] <- (zl[!is.finite(out)] + zr[!is.finite(out)]) / 2
  out
}


#' Insert new abscissae into the (sorted) hull support and rebuild the hull.
update_hull <- function(hull, new_x, new_h, new_hp, tol = 1e-8) {
  keep <- !duplicated(c(hull$x, new_x))
  x   <- c(hull$x, new_x)[keep]
  hx  <- c(hull$hx, new_h)[keep]
  hpx <- c(hull$hpx, new_hp)[keep]
  ord <- order(x)
  build_hull(x[ord], hx[ord], hpx[ord], hull$lower, hull$upper, tol = tol)
}


## ---------------------------------------------------------------------------
## 7. Main function
## ---------------------------------------------------------------------------

#' Adaptive rejection sampling (Gilks & Wild, 1992)
#'
#' @param density_function function / function name / expression in x giving the
#'        (possibly unnormalised) density, vectorized.
#' @param domain numeric vector of length 2 giving the support, may be infinite.
#' @param n number of samples to draw.
#' @param log_density set TRUE if `density_function` already returns log f.
#' @param max_points maximum number of abscissae kept in the hull.
#' @param ... further arguments passed on to `density_function`.
#' @return numeric vector of length n containing i.i.d. draws from the density.
ars <- function(density_function, domain = c(-Inf, Inf), n = 100,
                log_density = FALSE, max_points = 500L, ...) {

  checked <- validate_ars_inputs(density_function, domain, n)
  fun <- checked$fun; lower <- checked$lower; upper <- checked$upper
  n <- checked$n

  h      <- make_log_density(fun, ..., log_input = log_density)
  hprime <- make_log_density_derivative(h, lower, upper)

  x   <- initialize_abscissae(h, hprime, lower, upper)
  hx  <- h(x)
  hpx <- hprime(x)
  hull <- build_hull(x, hx, hpx, lower, upper)

  samples <- numeric(n)
  filled <- 0L
  iteration <- 0L
  max_iterations <- 1000L * n + 10000L

  while (filled < n) {
    iteration <- iteration + 1L
    if (iteration > max_iterations) {
      stop("ars: exceeded the maximum number of iterations without collecting ",
           n, " samples; the density may be badly behaved")
    }

    ## batch size grows with what is left to do (efficiency, same algorithm)
    batch <- max(1L, min(n - filled, 100L))
    x_star <- sample_upper_hull(hull, batch)
    w <- runif(batch)

    u_star <- eval_upper_hull(hull, x_star)
    l_star <- eval_lower_hull(hull, x_star)

    ## --- squeezing test ----------------------------------------------------
    squeezed <- log(w) <= (l_star - u_star)
    accepted <- squeezed

    ## --- rejection test (only where the squeeze failed) --------------------
    need <- which(!squeezed)
    new_x <- numeric(0); new_h <- numeric(0); new_hp <- numeric(0)
    if (length(need) > 0L) {
      h_star <- h(x_star[need])
      for (i in seq_along(need)) {
        check_envelope(x_star[need[i]], h_star[i], u_star[need[i]])
      }
      accepted[need] <- log(w[need]) <= (h_star - u_star[need])
      ## adapt: add the evaluated points to the hull
      ok <- is.finite(h_star)
      if (any(ok) && length(hull$x) < max_points) {
        cand <- x_star[need][ok]
        new_x  <- cand
        new_h  <- h_star[ok]
        new_hp <- hprime(cand)
      }
    }

    n_acc <- sum(accepted)
    if (n_acc > 0L) {
      take <- min(n_acc, n - filled)
      samples[(filled + 1L):(filled + take)] <- x_star[accepted][seq_len(take)]
      filled <- filled + take
    }

    if (length(new_x) > 0L) {
      hull <- update_hull(hull, new_x, new_h, new_hp)
    }
  }

  samples
}


