edits.new:
#' Check the two envelope inequalities implied by log-concavity at a sampled
#' point: the tangent (upper) hull must dominate log f, and the chord (lower)
#' hull must be dominated by log f.
check_envelope <- function(x_star, h_star, u_star, l_star = -Inf, tol = 1e-6) {
  if (is.finite(h_star) && h_star > u_star + tol * max(1, abs(u_star))) {
    stop(sprintf(paste0("ars: density is not log-concave - log f(%g) = %g exceeds ",
                        "the upper envelope (tangent) value %g"), x_star, h_star, u_star))
  }
  if (is.finite(l_star) && is.finite(h_star) &&
      h_star < l_star - tol * max(1, abs(l_star))) {
    stop(sprintf(paste0("ars: density is not log-concave - log f(%g) = %g lies below ",
                        "the chord (lower hull) value %g"), x_star, h_star, l_star))
  }
  if (is.finite(l_star) && !is.finite(h_star)) {
    stop(sprintf(paste0("ars: density is zero at x = %g but positive at surrounding ",
                        "abscissae - the support is not an interval (log-concavity violated)"),
                 x_star))
  }
  invisible(TRUE)
}

